// mux_driver.sv
// Converts sequence items into pin-level stimulus via the virtual interface.
// Since the interface has no clocking blocks and the DUT is combinational,
// we use a clock provided by tb_top for synchronization.
class mux_driver extends uvm_driver #(mux_seq_item);
  `uvm_component_utils(mux_driver)

  virtual mux_if vif;

  function new(string name = "mux_driver", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (!uvm_config_db#(virtual mux_if)::get(this, "", "vif", vif))
      `uvm_fatal(get_type_name(), "Failed to get virtual interface from config_db")
  endfunction

  virtual task run_phase(uvm_phase phase);
    mux_seq_item item;
    forever begin
      seq_item_port.get_next_item(item);
      drive_item(item);
      seq_item_port.item_done();
    end
  endtask

  // Drive signals onto the interface, then wait for a clock edge
  // to allow combinational logic to settle and monitor to sample
  virtual task drive_item(mux_seq_item item);
    #1;
    vif.in0 <= item.in0;
    vif.in1 <= item.in1;
    vif.in2 <= item.in2;
    vif.in3 <= item.in3;
    vif.sel <= item.sel;
    `uvm_info(get_type_name(), $sformatf("Driving: sel=%0b in0=%0h in1=%0h in2=%0h in3=%0h",
              item.sel, item.in0, item.in1, item.in2, item.in3), UVM_HIGH)
  endtask

