// mux_scoreboard.sv
// Reference model computes expected output and compares against actual DUT output
class mux_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(mux_scoreboard)

  uvm_analysis_imp #(mux_seq_item, mux_scoreboard) analysis_export;

  // Statistics
  int unsigned pass_count;
  int unsigned fail_count;

  function new(string name = "mux_scoreboard", uvm_component parent = null);
    super.new(name, parent);
    pass_count = 0;
    fail_count = 0;
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    analysis_export = new("analysis_export", this);
  endfunction

  // Reference model: compute expected output based on sel
  function logic [3:0] compute_expected(mux_seq_item item);
    case (item.sel)
      2'b00: return item.in0;
      2'b01: return item.in1;
      2'b10: return item.in2;
      2'b11: return item.in3;
      default: return 4'h0;
    endcase
  endfunction

  // Receive transaction from monitor and check
  virtual function void write(mux_seq_item item);
    logic [3:0] expected_out;
    expected_out = compute_expected(item);

    if (item.out === expected_out) begin
      pass_count++;
      `uvm_info(get_type_name(), $sformatf("PASS: sel=%0b, out=%0h (expected=%0h)",
                item.sel, item.out, expected_out), UVM_HIGH)
    end else begin
      fail_count++;
      `uvm_error(get_type_name(), $sformatf("FAIL: sel=%0b, out=%0h (expected=%0h) | in0=%0h in1=%0h in2=%0h in3=%0h",
                 item.sel, item.out, expected_out, item.in0, item.in1, item.in2, item.in3))
    end

    // Additional check: verify out matches one of the inputs (complements SVA OUT_VALID)
    if (!((item.out === item.in0) || (item.out === item.in1) ||
          (item.out === item.in2) || (item.out === item.in3))) begin
      `uvm_error(get_type_name(), $sformatf("OUT_VALID FAIL: out=%0h does not match any input", item.out))
    end

    // Check for X/Z (complements SVA NO_X_OUT, NO_X_SEL)
    if ($isunknown(item.out))
      `uvm_error(get_type_name(), "X/Z detected on output")
    if ($isunknown(item.sel))
      `uvm_error(get_type_name(), "X/Z detected on sel")
  endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info(get_type_name(), $sformatf("Scoreboard Summary: PASS=%0d, FAIL=%0d", pass_count, fail_count), UVM_LOW)
    if (fail_count > 0)
      `uvm_error(get_type_name(), $sformatf("%0d transactions FAILED!", fail_count))
    else
      `uvm_info(get_type_name(), "All transactions PASSED!", UVM_LOW)
  endfunction

endclass

