// mux_coverage.sv
// Functional coverage subscriber with covergroups for verification completeness
class mux_coverage extends uvm_subscriber #(mux_seq_item);
  `uvm_component_utils(mux_coverage)

  mux_seq_item item;

  // Covergroup for MUX functional coverage
  covergroup mux_cg;
    option.per_instance = 1;

    // Coverpoint for select signal — all values
    cp_sel: coverpoint item.sel {
      bins sel_00 = {2'b00};
      bins sel_01 = {2'b01};
      bins sel_10 = {2'b10};
      bins sel_11 = {2'b11};
    }

    // Coverpoints for each input — boundary and mid values
    cp_in0: coverpoint item.in0 {
      bins zero     = {4'h0};
      bins max_val  = {4'hF};
      bins mid_low  = {[4'h1:4'h7]};
      bins mid_high = {[4'h8:4'hE]};
    }

    cp_in1: coverpoint item.in1 {
      bins zero     = {4'h0};
      bins max_val  = {4'hF};
      bins mid_low  = {[4'h1:4'h7]};
      bins mid_high = {[4'h8:4'hE]};
    }

    cp_in2: coverpoint item.in2 {
      bins zero     = {4'h0};
      bins max_val  = {4'hF};
      bins mid_low  = {[4'h1:4'h7]};
      bins mid_high = {[4'h8:4'hE]};
    }

    cp_in3: coverpoint item.in3 {
      bins zero     = {4'h0};
      bins max_val  = {4'hF};
      bins mid_low  = {[4'h1:4'h7]};
      bins mid_high = {[4'h8:4'hE]};
    }

    // Output coverpoint
    cp_out: coverpoint item.out {
      bins zero     = {4'h0};
      bins max_val  = {4'hF};
      bins mid_low  = {[4'h1:4'h7]};
      bins mid_high = {[4'h8:4'hE]};
    }

    // Cross coverage: sel x input value ranges
    cx_sel_in0: cross cp_sel, cp_in0;
    cx_sel_in1: cross cp_sel, cp_in1;
    cx_sel_in2: cross cp_sel, cp_in2;
    cx_sel_in3: cross cp_sel, cp_in3;

    // Cross coverage: sel x output
    cx_sel_out: cross cp_sel, cp_out;

    // All inputs identical
    cp_all_same: coverpoint (item.in0 == item.in1 && item.in1 == item.in2 && item.in2 == item.in3) {
      bins all_same     = {1'b1};
      bins not_all_same = {1'b0};
    }

    // All inputs unique
    cp_all_unique: coverpoint (item.in0 != item.in1 && item.in0 != item.in2 && item.in0 != item.in3 &&
                               item.in1 != item.in2 && item.in1 != item.in3 &&
                               item.in2 != item.in3) {
      bins all_unique     = {1'b1};
      bins not_all_unique = {1'b0};
    }

    // Sel transitions (requires sampling over time)
    cp_sel_trans: coverpoint item.sel {
      bins trans_00_01 = (2'b00 => 2'b01);
      bins trans_01_10 = (2'b01 => 2'b10);
      bins trans_10_11 = (2'b10 => 2'b11);
      bins trans_11_00 = (2'b11 => 2'b00);
      bins trans_00_11 = (2'b00 => 2'b11);
      bins trans_11_01 = (2'b11 => 2'b01);
    }
  endgroup

  function new(string name = "mux_coverage", uvm_component parent = null);
    super.new(name, parent);
    mux_cg = new();
  endfunction

  // Called each time a transaction is received from the monitor
  virtual function void write(mux_seq_item t);
    item = t;
    mux_cg.sample();
    `uvm_info(get_type_name(), $sformatf("Coverage sampled: sel=%0b out=%0h", t.sel, t.out), UVM_HIGH)
  endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info(get_type_name(), $sformatf("Functional Coverage: %.2f%%", mux_cg.get_coverage()), UVM_LOW)
  endfunction

endclass

