// mux_agent.sv
// UVM agent bundling driver, sequencer, and monitor. Supports ACTIVE/PASSIVE modes.
class mux_agent extends uvm_agent;
  `uvm_component_utils(mux_agent)

  mux_driver    m_driver;
  mux_sequencer m_sequencer;
  mux_monitor   m_monitor;

  function new(string name = "mux_agent", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);

    // Monitor is always instantiated (both ACTIVE and PASSIVE)
    m_monitor = mux_monitor::type_id::create("m_monitor", this);

    // Driver and sequencer only in ACTIVE mode
    if (get_is_active() == UVM_ACTIVE) begin
      m_driver    = mux_driver::type_id::create("m_driver", this);
      m_sequencer = mux_sequencer::type_id::create("m_sequencer", this);
      `uvm_info(get_type_name(), "Agent configured in ACTIVE mode", UVM_MEDIUM)
    end else begin
      `uvm_info(get_type_name(), "Agent configured in PASSIVE mode", UVM_MEDIUM)
    end
  endfunction

  function void connect_phase(uvm_phase phase);
    super.connect_phase(phase);
    if (get_is_active() == UVM_ACTIVE) begin
      m_driver.seq_item_port.connect(m_sequencer.seq_item_export);
    end
  endfunction

endclass

