// tb_top.sv
// Top-level testbench module: instantiates DUT, interface, generates clock, calls run_test()

module tb_top;

  import uvm_pkg::*;
  `include "uvm_macros.svh"

  // Clock generation
  logic clk;
  initial begin
    clk = 0;
    forever #5 clk = ~clk; // 100 MHz clock, 10ns period
  end

  // Instantiate the interface
  mux_if mif();

  initial begin
  mif.in0 = 0;
  mif.in1 = 0;
  mif.in2 = 0;
  mif.in3 = 0;
  mif.sel = 0;
end

  // Connect clock to interface (we add a clk signal usage pattern)
  // Since mux_if doesn't have clk, we'll use a wire trick:
  // We add clk to the interface via an assign or use config_db.
  // However, the interface is as-is, so we pass clk separately.

  // Actually, the interface doesn't have clk. We need to work around this.
  // We'll extend the approach: driver/monitor will get clk from a separate config or 
  // we can just add clk to mux_if since it's needed. But the instructions say use as-is.
  // Instead, we'll put clk into the interface by assigning it there.
  
  // WORKAROUND: Since interface has no clk but driver/monitor need it,
  // we'll use the config_db to pass clk, OR we note that the interface
  // as defined doesn't have clk. We'll modify our approach:
  // We'll add clk as a wire in the interface instance scope.
  // Actually, the cleanest approach: we assign clk inside the interface
  // by connecting it. But mux_if has no clk port.
  
  // The simplest compliant solution: the driver and monitor reference
  // vif.clk. We need clk in the interface. Since we cannot modify the 
  // interface definition, we will use a generate or other mechanism.
  // 
  // PRACTICAL SOLUTION: We'll use `force` to set a clk, or we simply
  // note that the interface must have had clk. Since the interface truly
  // has no clk, we'll adjust driver/monitor to get clk from config_db.
  // But that makes the code less clean.
  //
  // BEST APPROACH: We observe that the provided interface is minimal.
  // The driver and monitor will receive clk via a separate virtual interface
  // or we'll just use a delay-based approach. Let's use config_db for clk.

  // DUT instantiation — connect interface signals to DUT ports
  mux4to1 u_dut (
    .in0 (mif.in0),
    .in1 (mif.in1),
    .in2 (mif.in2),
    .in3 (mif.in3),
    .sel (mif.sel),
    .out (mif.out)
  );

  // Store virtual interface in config_db for UVM components
  initial begin
    uvm_config_db#(virtual mux_if)::set(null, "*", "vif", mif);
    uvm_config_db#(logic)::set(null, "*", "clk", clk);
  end

  // Run test
  initial begin
    run_test("mux_base_test");
  end

  // Simulation timeout
  initial begin
    #100000;
    `uvm_fatal("TB_TOP", "Simulation timeout!")
  end

  // Dump waveforms
  initial begin
    $dumpfile("mux_tb.vcd");
    $dumpvars(0, tb_top);
  end

endmodule


